import re
rows = [l for l in open('workspace/GAMES.md') if re.match('^\\|\\s*\\d+\\s*\\|', l)]
data = {}
for l in rows:
    c = [x.strip() for x in l.strip().strip('|').split('|')]
    try:
        g = int(c[0])
    except:
        continue
    data[g] = (c[1], c[2], c[3])
print('rows', len(data), 'max', max(data))

def score(res, col):
    r = res.split()[0]
    if r == '1/2-1/2' or r.startswith('1/2'):
        return 0.5
    if r == '1-0':
        return 1.0 if col == 'W' else 0.0
    if r == '0-1':
        return 1.0 if col == 'B' else 0.0
    return None
for lo, hi in [(1, 50), (51, 100), (101, 150), (151, 200), (1, 100), (101, 200)]:
    agg = {}
    for g in range(lo, hi + 1):
        if g not in data:
            continue
        o, col, res = data[g]
        s = score(res, col)
        a = agg.setdefault(o, [0, 0, 0, 0])
        if s is None:
            a[3] += 1
            continue
        if s == 1:
            a[0] += 1
        elif s == 0.5:
            a[1] += 1
        else:
            a[2] += 1
    print(lo, hi, {k: tuple(v) for k, v in agg.items()})

